import React, { InputHTMLAttributes } from "react";

import { useStableId } from "../hooks/useStableId.js";
import styles from "./CyberpunkSlider.module.css";

export interface CyberpunkSliderProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, "type" | "helperText"> {
  label?: string;
  min?: number;
  max?: number;
  step?: number;
  showValue?: boolean;
  helperText?: string;
  error?: string;
}

/** Fill percentage for the track; 0 when max===min or non-finite. Clamped to [0, 100]. */
export function sliderPercentage(
  value: number | string,
  min: number,
  max: number,
): number {
  const range = max - min;
  const percentage = range === 0 ? 0 : ((Number(value) - min) / range) * 100;
  return Number.isFinite(percentage)
    ? Math.min(100, Math.max(0, percentage))
    : 0;
}

export function CyberpunkSlider({
  label,
  className = "",
  id,
  min = 0,
  max = 100,
  step = 1,
  showValue = true,
  value = 0,
  helperText,
  error,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
  ...props
}: CyberpunkSliderProps) {
  const inputId = useStableId("slider", id);
  const helperId = useStableId("slider-helper");
  const errorId = useStableId("slider-error");
  const hasError = Boolean(error);
  const percentage = sliderPercentage(value as number | string, min, max);
  const describedBy =
    [
      ariaDescribedBy,
      helperText ? helperId : undefined,
      hasError ? errorId : undefined,
    ]
      .filter(Boolean)
      .join(" ") || undefined;

  return (
    <div className={`${styles.wrapper} ${hasError ? styles.hasError : ""} ${className}`.trim()}>
      {label ? (
        <label htmlFor={inputId} className={styles.label}>
          {label}
        </label>
      ) : null}
      <div className={styles.sliderContainer}>
        <input
          id={inputId}
          type="range"
          min={min}
          max={max}
          step={step}
          value={value}
          className={styles.slider}
          style={
            {
              ["--slider-percentage" as string]: `${percentage}%`,
            } as React.CSSProperties
          }
          {...props}
          aria-invalid={ariaInvalid ?? (hasError ? true : undefined)}
          aria-describedby={describedBy}
        />
        {showValue ? <span className={styles.value}>{value}</span> : null}
      </div>
      {helperText ? (
        <div id={helperId} className={styles.helperText}>
          {helperText}
        </div>
      ) : null}
      {hasError ? (
        <div id={errorId} className={styles.errorText} role="alert">
          {error}
        </div>
      ) : null}
    </div>
  );
}

.wrapper {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.label {
  font-size: 0.875rem;
  color: var(--text-primary);
  font-weight: 500;
}

.sliderContainer {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.slider {
  flex: 1;
  height: 32px;
  border: 2px solid var(--border);
  border-radius: 16px;
  appearance: none;
  outline: none;
  cursor: pointer;
  transition: all var(--transition-fast);
  padding-right: 14px;
  margin-right: -14px;
  background: linear-gradient(
    to right,
    var(--success) 0%,
    var(--success) var(--slider-percentage, 0%),
    var(--bg-primary) var(--slider-percentage, 0%),
    var(--bg-primary) 100%
  );
}

.slider::-webkit-slider-track {
  width: calc(100% + 14px);
  height: 28px;
  border-radius: 14px;
  background: transparent;
}

.slider::-webkit-slider-thumb {
  appearance: none;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--success);
  cursor: pointer;
  box-shadow: 0 0 10px rgba(0, 255, 136, 0.4);
  transition: all var(--transition-fast);
  border: 2px solid rgba(0, 255, 136, 0.2);
}

.slider::-moz-range-track {
  width: calc(100% + 14px);
  height: 28px;
  border-radius: 14px;
  background: transparent;
  border: none;
}

.slider::-moz-range-thumb {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--success);
  cursor: pointer;
  border: 2px solid rgba(0, 255, 136, 0.2);
  box-shadow: 0 0 10px rgba(0, 255, 136, 0.4);
  transition: all var(--transition-fast);
}

.slider:hover {
  border-color: var(--success);
}

.slider:focus-visible {
  box-shadow: 0 0 0 2px rgba(0, 255, 136, 0.2);
}

.slider:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.value {
  font-size: 0.875rem;
  color: var(--success);
  font-weight: 600;
  min-width: 3rem;
  text-align: center;
  font-family: var(--font-mono);
}

.helperText {
  margin-top: 0.25rem;
  font-size: 0.75rem;
  color: var(--text-secondary);
  font-family: var(--font-mono);
}

.hasError .label {
  color: var(--danger, #ff5c5c);
}

.errorText {
  margin-top: 0.35rem;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  color: var(--danger, #ff5c5c);
  line-height: 1.3;
}

import { useId } from "react";

export function useStableId(prefix: string, explicitId?: string): string {
  const reactId = useId().replace(/:/g, "");
  return explicitId || `${prefix}-${reactId}`;
}
